def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # {key: (value, write_time)}
    results = []

    for op in ops:
        if op[0] == 'put':
            t, key, value = op[1], op[2], op[3]
            # Remove expired entries
            keys_to_delete = [k for k, (v, wt) in cache.items() if wt + ttl <= t]
            for k in keys_to_delete:
                del cache[k]

            # If key exists, remove it to re-add it at the end (most recently used)
            if key in cache:
                del cache[key]
            # If cache is at capacity and key is not present, evict LRU
            elif len(cache) >= capacity:
                cache.popitem(last=False)  # Remove first (oldest) item

            # Add the new entry
            cache[key] = (value, t)

        elif op[0] == 'get':
            t, key = op[1], op[2]
            # Remove expired entries
            keys_to_delete = [k for k, (v, wt) in cache.items() if wt + ttl <= t]
            for k in keys_to_delete:
                del cache[k]

            # Get the value or return -1
            if key in cache:
                value, _ = cache[key]
                # Move to end (most recently used)
                del cache[key]
                cache[key] = (value, cache.get(key, (None, None))[1] if key in cache else _)
                # Re-fetch to preserve write time
                write_time = None
                for k, (v, wt) in cache.items():
                    if k == key:
                        write_time = wt
                        break
                # Simpler approach: just move the item
                cache.move_to_end(key)
                results.append(value)
            else:
                results.append(-1)

    return results

